CREATE TABLE public.assistant_threads (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, title text NOT NULL DEFAULT 'New chat', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.assistant_threads TO authenticated;
GRANT ALL ON public.assistant_threads TO service_role;
ALTER TABLE public.assistant_threads ENABLE ROW LEVEL SECURITY;
CREATE POLICY assistant_threads_owner ON public.assistant_threads FOR ALL TO authenticated USING (user_id = auth.uid() AND public.has_role(auth.uid(), 'admin')) WITH CHECK (user_id = auth.uid() AND public.has_role(auth.uid(), 'admin'));
CREATE TABLE public.assistant_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), thread_id uuid NOT NULL REFERENCES public.assistant_threads(id) ON DELETE CASCADE, role text NOT NULL CHECK (role IN ('user','assistant')), parts jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT ON public.assistant_messages TO authenticated;
GRANT ALL ON public.assistant_messages TO service_role;
ALTER TABLE public.assistant_messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY assistant_messages_read ON public.assistant_messages FOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'admin') AND EXISTS (SELECT 1 FROM public.assistant_threads t WHERE t.id = thread_id AND t.user_id = auth.uid()));
CREATE POLICY assistant_messages_insert ON public.assistant_messages FOR INSERT TO authenticated WITH CHECK (role = 'user' AND public.has_role(auth.uid(), 'admin') AND EXISTS (SELECT 1 FROM public.assistant_threads t WHERE t.id = thread_id AND t.user_id = auth.uid()));
CREATE TABLE public.assistant_activity (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, thread_id uuid REFERENCES public.assistant_threads(id) ON DELETE SET NULL, action text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.assistant_activity TO authenticated;
GRANT ALL ON public.assistant_activity TO service_role;
ALTER TABLE public.assistant_activity ENABLE ROW LEVEL SECURITY;
CREATE POLICY assistant_activity_read ON public.assistant_activity FOR SELECT TO authenticated USING (user_id = auth.uid() AND public.has_role(auth.uid(), 'admin'));
CREATE INDEX assistant_messages_thread_time ON public.assistant_messages(thread_id, created_at);
CREATE INDEX assistant_threads_owner_time ON public.assistant_threads(user_id, updated_at DESC);
CREATE FUNCTION public.assistant_message_saved() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN UPDATE public.assistant_threads SET title = CASE WHEN title = 'New chat' THEN left(NEW.parts->0->>'text', 70) ELSE title END, updated_at = now() WHERE id = NEW.thread_id; RETURN NEW; END $$;
CREATE TRIGGER assistant_message_saved AFTER INSERT ON public.assistant_messages FOR EACH ROW EXECUTE FUNCTION public.assistant_message_saved();
CREATE FUNCTION public.assistant_clear_conversation(p_thread_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF NOT public.has_role(auth.uid(), 'admin') OR NOT EXISTS (SELECT 1 FROM public.assistant_threads WHERE id = p_thread_id AND user_id = auth.uid()) THEN RAISE EXCEPTION 'Forbidden'; END IF; DELETE FROM public.assistant_messages WHERE thread_id = p_thread_id; UPDATE public.assistant_threads SET title = 'New chat', updated_at = now() WHERE id = p_thread_id; INSERT INTO public.assistant_activity(user_id,thread_id,action) VALUES (auth.uid(),p_thread_id,'conversation_cleared'); END $$;
REVOKE ALL ON FUNCTION public.assistant_clear_conversation(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.assistant_clear_conversation(uuid) TO authenticated;
REVOKE ALL ON FUNCTION public.assistant_message_saved() FROM PUBLIC, anon, authenticated;